select.if:
SELECT WFL.TRADE_ID tradeId, WFL.WORKFLOW_STATUS tradeStatus, WFLDEAL.ENTRUST_ID entrustId, WFLDEAL.PORTFOLIO_ID portfolioId, PTL.PORTFOLIO_NAME portfolioName, WFL.FINPROD_TYPE2 finprodType, WFL.FINPROD_ID finprodIdHide, WFLDEAL.EXC_DEAL_TYPE excDealType, WFLDEAL.CUR_PAIR curPair, WFLTPDO.EXC_PS ps, WFLTPDO.DEAL_CUR dealCur, WFL.CCY corCcy, WFLTPDO.EXC_FXS_TERM_TYPE excFxsTermType, WFL.TRADE_DATE tradeDate, WFL.UNIT_CPRICE spotRate, WFLDEAL.TERM_TYPE nTermTypeExc, WFL.SETTLE_DATE vdate, WFL.UNIT_INT nPoint, WFL.UNIT_FPRICE nFprice, WFL.PRIN_AMT nDealCurAmt, WFL.TRADE_AMT nCorCurAmt, WFLDEAL.USD_AMT nUsdAmt, WFLTPDO.TERM_TYPE fTermTypeExc, WFLTPDO.F_MDATE mdate, WFLTPDO.FWD_POINT fPoint, WFLTPDO.FWD_FPRICE fFprice, WFLTPDO.F_DEAL_AMT fDealCurAmt, WFLTPDO.F_COR_AMT fCorCurAmt, WFLTPDO.F_USD_AMT fUsdAmt, WFL.REMARK remark, null calendarId, null holdPurpose, WFLDEAL.OUR_ROLE ourRole, null dealMode, WFL.DELIVERY_TYPE settMode, WFL.FEE_AMT feeAmt, WFL.COUNTER_ID CounterId, WFL.TRADER trader, WFL.COUNTER_TRADER counterTrader, WFL.COUNTER_CONTACT counterContact, WFL.WORKFLOW_ID workflowId, WFL.WORKFLOW_STATUS workflowStatus, null tradeId1 FROM WFL_TRD_PRODUCT_DEAL WFL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL_OTH WFLTPDO ON WFL.TRADE_ID = WFLTPDO.TRADE_ID LEFT JOIN PTL_PORTFOLIO PTL ON WFLDEAL.PORTFOLIO_ID = PTL.PORTFOLIO_ID
and (PTL.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) or PTL.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) )
AND WFL.FINPROD_TYPE2 = #{finprodType2}
AND ( PTL.PORTFOLIO_ID IN
#{item}
or PTL.PARENT_PORTFOLIO_ID IN
#{item}
)
AND WFLDEAL.ENTRUST_ID = #{entrustId}
AND WFLDEAL.EXC_DEAL_TYPE = #{excDealType}
AND WFLDEAL.CUR_PAIR IN
#{item}
AND WFLTPDO.EXC_PS = #{ps}
AND WFLTPDO.EXC_FXS_TERM_TYPE IN
#{item}
AND WFL.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
AND WFL.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
AND WFL.SETTLE_DATE >= STR_TO_DATE(#{vDateBegin},'%Y-%m-%d')
AND WFL.SETTLE_DATE <= STR_TO_DATE(#{vDateEnd},'%Y-%m-%d')
AND WFLTPDO.F_MDATE >= STR_TO_DATE(#{mDateBegin},'%Y-%m-%d')
AND WFLTPDO.F_MDATE <= STR_TO_DATE(#{mDateEnd},'%Y-%m-%d')
AND WFL.WORKFLOW_STATUS = #{tradeFlowStatus}
AND WFL.TRADE_ID = #{tradeId} AND WFL.WORKFLOW_STATUS = #{tradeStatus}

SELECT WFL.TRADE_ID tradeId, case WFL.TRADE_STATUS when #{validStatus_03} then #{validStatus_03} else #{validStatus_02} end tradeStatus, WFLDEAL.ENTRUST_ID entrustId, PTL.PORTFOLIO_ID portfolioId, PTL.PORTFOLIO_NAME portfolioName, WFL.FINPROD_TYPE2 finprodType, WFL.FINPROD_ID finprodIdHide, WFLDEAL.EXC_DEAL_TYPE excDealType, WFLDEAL.CUR_PAIR curPair, FINTP.EXC_PS ps, FINTP.CCY dealCur, WFL.CCY corCcy, FINTP.EXC_FXS_TERM_TYPE excFxsTermType, WFL.TRADE_DATE tradeDate, WFL.UNIT_CPRICE spotRate, WFLDEAL.TERM_TYPE nTermTypeExc, WFL.SETTLE_DATE vdate, WFL.UNIT_INT nPoint, WFL.UNIT_FPRICE nFprice, WFL.PRIN_AMT nDealCurAmt, WFL.TRADE_AMT nCorCurAmt, WFLDEAL.USD_AMT nUsdAmt, FINTP.TERM_TYPE fTermTypeExc, FINTP.MDATE mdate, FINTP.M_UNIT_INT fPoint, FINTP.M_UNIT_FPRICE fFprice, FINTP.M_PRIN_AMT fDealCurAmt, FINTP.M_TRADE_AMT fCorCurAmt, FINTP.USD_AMT fUsdAmt, WFL.REMARK remark, FINTP.CALENDAR_ID calendarId, FINTP.HOLD_PURPOSE holdPurpose, WFLDEAL.OUR_ROLE ourRole, WFLDEAL.DEAL_MODE dealMode, WFL.DELIVERY_TYPE settMode, WFL.FEE_AMT feeAmt, WFL.COUNTER_ID CounterId, WFL.TRADER trader, WFL.COUNTER_TRADER counterTrader, WFL.COUNTER_CONTACT counterContact, null workflowId, null workflowStatus, deal2.TRADE_ID tradeId1 FROM TRD_PRODUCT_DEAL WFL LEFT JOIN TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FINTP ON WFL.FINPROD_ID = FINTP.FINPROD_ID LEFT JOIN PTL_TRADE PT ON IFNULL(WFL.P_TRADE_ID,WFL.TRADE_ID) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PTL ON PT.PORTFOLIO_ID = PTL.PORTFOLIO_ID LEFT JOIN TRD_PRODUCT_DEAL deal2 ON deal2.FINPROD_ID = WFL.FINPROD_ID and deal2.FINPROD_TYPE2 = WFL.FINPROD_TYPE2 and deal2.TRADE_STATUS = WFL.TRADE_STATUS and deal2.PS != WFL.PS
PTL.INVEST_YESORNO='Y'
AND WFL.PS = #{psBuy}
and (PTL.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) or PTL.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) )
AND WFL.FINPROD_TYPE2 = #{finprodType2}
AND (PTL.PORTFOLIO_ID IN
#{item}
OR PTL.PARENT_PORTFOLIO_ID IN
#{item}
)
AND WFLDEAL.ENTRUST_ID = #{entrustId}
AND WFLDEAL.EXC_DEAL_TYPE = #{excDealType}
AND WFLDEAL.CUR_PAIR IN
#{item}
AND FINTP.EXC_PS = #{ps}
AND FINTP.EXC_FXS_TERM_TYPE IN
#{item}
AND WFL.TRADE_STATUS =#{validStatus_01} AND WFL.IS_CANCEL != 'Y'
AND WFL.TRADE_STATUS =#{validStatus_03} AND WFL.IS_CANCEL != 'Y'
AND WFL.IS_CANCEL != 'Y'
AND WFL.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
AND WFL.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
AND WFL.SETTLE_DATE >= STR_TO_DATE(#{vDateBegin},'%Y-%m-%d')
AND WFL.SETTLE_DATE <= STR_TO_DATE(#{vDateEnd},'%Y-%m-%d')
AND FINTP.MDATE >= STR_TO_DATE(#{mDateBegin},'%Y-%m-%d')
AND FINTP.MDATE <= STR_TO_DATE(#{mDateEnd},'%Y-%m-%d')
AND WFL.TRADE_ID = #{tradeId} AND case WFL.TRADE_STATUS when #{validStatus_03} then #{validStatus_03} else #{validStatus_02} end = #{tradeStatus}
